        R("Recording started — CSV/JSON will be available afterwards.", "Kayıt başladı — CSV/JSON daha sonra kullanılabilir olacak.", "Aufzeichnung gestartet – CSV/JSON stehen danach zur Verfügung.", "Nagrywanie rozpoczęte — CSV/JSON będą dostępne później.", "Grabación iniciada: CSV/JSON estarán disponibles después.", "Gravação iniciada — CSV/JSON ficarão disponíveis depois.", "Enregistrement démarré — le CSV/JSON sera disponible ensuite.", "Registrazione avviata: CSV/JSON saranno disponibili dopo."),
        R("No recorded Live Data sessions yet.", "Henüz kaydedilmiş Canlı Veri oturumu yok.", "Noch keine aufgezeichneten Live-Daten-Sitzungen.", "Brak jeszcze nagranych sesji danych na żywo.", "Aún no hay sesiones de datos en vivo grabadas.", "Ainda não há sessões de dados em direto gravadas.", "Aucune session de données en direct enregistrée pour le moment.", "Ancora nessuna sessione di dati live registrata."),
        R("No recorded Live Data sessions yet. Start recording real OBD data with Record.", "Henüz kaydedilmiş Canlı Veri oturumu yok. Kaydet ile gerçek OBD verilerini kaydetmeye başlayın.", "Noch keine aufgezeichneten Live-Daten-Sitzungen. Starte die Aufzeichnung echter OBD-Daten mit Aufnahme.", "Brak jeszcze nagranych sesji danych na żywo. Rozpocznij nagrywanie rzeczywistych danych OBD przyciskiem Nagraj.", "Aún no hay sesiones de datos en vivo grabadas. Empieza a grabar datos OBD reales con Grabar.", "Ainda não há sessões de dados em direto gravadas. Comece a gravar dados OBD reais com Gravar.", "Aucune session de données en direct enregistrée pour le moment. Commencez à enregistrer des données OBD réelles avec Enregistrer.", "Ancora nessuna sessione di dati live registrata. Inizia a registrare dati OBD reali con Registra."),
        R("No recorded sessions yet.", "Henüz kaydedilmiş oturum yok.", "Noch keine aufgezeichneten Sitzungen.", "Brak jeszcze nagranych sesji.", "Aún no hay sesiones grabadas.", "Ainda não há sessões gravadas.", "Aucune session enregistrée pour le moment.", "Ancora nessuna sessione registrata."),
        R("Very good — fast response", "Çok iyi — hızlı yanıt", "Sehr gut – schnelle Antwort", "Bardzo dobrze — szybka odpowiedź", "Muy bien: respuesta rápida", "Muito bom — resposta rápida", "Très bien — réponse rapide", "Molto bene: risposta rapida"),
