        R("The price will be shown from the Store", "Fiyat Mağaza'dan gösterilecek", "Der Preis wird aus dem Store angezeigt", "Cena zostanie pokazana ze sklepu", "El precio se mostrará desde la tienda", "O preço será mostrado a partir da loja", "Le prix sera affiché depuis le Store", "Il prezzo verrà mostrato dallo Store"),
        R("PRO activated successfully.", "PRO başarıyla etkinleştirildi.", "PRO erfolgreich aktiviert.", "PRO aktywowano pomyślnie.", "PRO activado correctamente.", "PRO ativado com sucesso.", "PRO activé avec succès.", "PRO attivato con successo."),
        R("PRO is already active.", "PRO zaten etkin.", "PRO ist bereits aktiv.", "PRO jest już aktywne.", "PRO ya está activo.", "O PRO já está ativo.", "PRO est déjà actif.", "PRO è già attivo."),
